%[text] # Receiver
%[text] 
rng(1) % Set seed for repeatability

fs = 50e3;
Rs = fs/8; % Quarter Nyquist nyquist
samples_per_symbol = ceil(fs/Rs);

fc = fs/4;

t = 0:1/fs: (10e3/fs) - 1/fs;
T = t(end);
%[text] ## RRC
rrc_filter_tx = comm.RaisedCosineTransmitFilter( ...
        RolloffFactor=0.3, ...
        Shape='Normal', ...
        OutputSamplesPerSymbol=samples_per_symbol);
rrc_filter_tx.Gain = 1/sum(rrc_filter_tx.coeffs.Numerator) %[output:3758af0a]

rrc_filter_rx = comm.RaisedCosineReceiveFilter( ...
    "RolloffFactor",0.3, ...
    "DecimationFactor",samples_per_symbol/2 ...
    );



%[text] 
nbits = ceil(T*Rs);
s2_bits = round(rand(1,floor(nbits)));
s2_signal = pskmod(s2_bits,2,0,PlotConstellation=true); %[output:162c04ab]

%s2 = s2_signal;
s2 = rrc_filter_tx(s2_signal);
s2 = s2(:)';
max(s2) %[output:4cef1c14]

